const CountContext = createContext(null);
const NameContext = createContext(null);

function CountButton() {
  const { count, setCount } = useContext(CountContext);
  return <button onClick={() => setCount(c => c + 1)}>+1 ({count})</button>;
}

function NameLabel() {
  const { name } = useContext(NameContext);
  return <p>Name: {name}</p>;
}

function App() {
  const [count, setCount] = useState(0);
  const [name, setName] = useState('Ada');
  return (
    <CountContext.Provider value={{ count, setCount }}>
      <NameContext.Provider value={{ name, setName }}>
        <div style={{ fontFamily: 'system-ui', padding: 16 }}>
          <CountButton />
          <NameLabel />
        </div>
      </NameContext.Provider>
    </CountContext.Provider>
  );
}

function createStore(initial) {
  let state = initial;
  const listeners = new Set();
  const getState = () => state;
  const setState = (partial) => {
    state = { ...state, ...(typeof partial === 'function' ? partial(state) : partial) };
    listeners.forEach(l => l());
  };
  const subscribe = (l) => { listeners.add(l); return () => listeners.delete(l); };
  return { getState, setState, subscribe };
}

const store = createStore({ count: 0, name: 'Ada' });

function useStore(selector) {
  const [slice, setSlice] = useState(() => selector(store.getState()));
  useEffect(() => {
    return store.subscribe(() => {
      const next = selector(store.getState());
      setSlice(prev => (prev === next ? prev : next));
    });
  }, []);
  return slice;
}

function Count() {
  const count = useStore(s => s.count);
  return <button onClick={() => store.setState(s => ({ count: s.count + 1 }))}>count {count}</button>;
}

function Name() {
  const name = useStore(s => s.name);
  return <p>name: {name}</p>;
}

function App() {
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <Count />
      <Name />
    </div>
  );
}
